must(kpr('fd001', Q0, 'STW_window', P1R).v === 'theirs' && kpr('fd001', Q0, 'STW_cost_1se', P1R).v === 'theirs', 'FD001: their policy 1 (P-res) beats the window-tuned and 1-SE alarms at c_p/c_c = 0.1');
