const w1 = kt('fd001', Q0, 'STW_window'), s1 = kt('fd001', Q0, 'STW_cost_1se'), r1 = kt('fd001', Q0, P1R), c1 = kt('fd001', Q0, P1C), p31 = kt('fd001', Q0, 'P3_res60'), wu1 = kt('fd001', Q0, 'STW_window_unmapped');
