B.push(H1('9. Discussion', 'disc'));
must(['PHM08', 'FD001', 'FD002', 'FD003', 'FD004', 'Battery'].every(d => ageWinDS.includes(d)) && ageWinDS.length === 6 && ageNoneDS[0] === 'NCMAPSS6', 'window-tuned alarms significantly cheaper than age replacement in at least 12 of 16 cells on the five C-MAPSS datasets and the batteries (convention C), in none on N-CMAPSS');
